import {esc as e,fmt as f,safeUrl} from './lib.js?v=20261101-short1';
import {metricSummary} from './core-metrics.js?v=20261101-short1';
const pct=x=>x==null?'—':f(x*100,1)+'%',sec=x=>x==null?'—':f(x/1000,3)+' s',usd=x=>x==null?'—':'$'+f(x,6);
const stateNames={implemented:'已实现 · 离线验收',review:'复核流程可用',blocked:'缺执行环境',planned:'尚未接入'};
const costNames={available:'费用齐备且判定完成',unmeasured:'未采集',unknown_cost:'存在未知费用',pending_review:'有人工待评',no_qualified:'无合格结果'};
const cell=(value,note='')=>`${value}${note?`<small>${e(note)}</small>`:''}`;

export function systemView(framework){
 return `<div class="notice"><strong>适合当前条件的实施范围</strong>　本机Windows，Python/Node已有；本轮新增API费用0。保留静态站＋离线运行器。新协议无真实成绩；72次模拟仅验证系统。未验证隔离执行环境，代码pass@1不发布。</div><div class="table-wrap"><table class="definition-table"><thead><tr><th>维度 / 指标</th><th>方法与单位</th><th>参考 / 评分口径</th><th>实现状态与边界</th></tr></thead><tbody>${framework.rows.map(r=>`<tr><td><strong>${e(r.title)}</strong><small>${e(r.group)} · ${e(r.id)}</small></td><td>${e(r.method)}<small>${e(r.unit)}</small></td><td>${safeUrl(r.sourceUrl)?`<a class="source" href="${e(safeUrl(r.sourceUrl))}" target="_blank" rel="noopener noreferrer">${e(r.reference)} ↗</a>`:e(r.reference)}<small>${e(r.scoring)}</small></td><td><span class="tag">${stateNames[r.state]||e(r.state)}</span><small>${e(r.limit)}</small></td></tr>`).join('')}</tbody></table></div><section class="panel"><div class="panel-body prose"><h2>成绩发布规则</h2><p>能力、性能、可靠性、成本分别呈现，不合成智力总分。官方benchmark复现按原协议；本站扩展明确标注。未测、未评、不支持和失败分别记录。</p><p>每条结果保留协议、题库、模型/服务商、用量、原始证据和评分依据。既有90条实测为历史流程样本，不能代表新题库成绩。</p><p>题库难度和区分度未做真实校准。18道自动题只验证已声明的规则；6道人工题不自动填分。新旧TPS按版本分开；未知价格不补零，规格不当能力。</p><p>本页面状态指程序/流程的实现情况，不表示已有真实模型成绩。当前协议：${e(framework.metricProtocol)} / ${e(framework.gradingProtocol)}。</p></div></section>`;
}

export function metricsView(data){
 const summaries=data.models.map(m=>({m,s:metricSummary(data,m.id)}));
 return `<div class="notice">新协议正文TPS排除首块；缺少可靠首块token计数时留空。端到端速率包含等待，两者不混用。旧口径仅在历史列显示。内容分、格式、自动题交付和完整返回分别阅读。</div>${!data.runs.length?'<div class="notice"><strong>当前范围尚未采集</strong>　规则和程序已就绪，真实成绩为空。可以切换“新协议离线验收 · 模拟”检查功能，或切换历史记录查看旧证据。</div>':''}<section class="panel"><div class="panel-head"><h2>质量与交付</h2><small>当前范围；按题、再按题族等权</small></div><div class="table-wrap"><table><thead><tr><th>配置</th><th>内容分</th><th>格式全满足率</th><th>约束细项满足率</th><th>自动题合格交付</th><th>完整返回</th><th>合格判定覆盖</th><th>合格结果费用</th></tr></thead><tbody>${summaries.map(({m,s})=>`<tr><td><button class="link" data-model="${e(m.id)}">${e(m.name)}</button></td><td>${cell(pct(s.content),`${s.contentTasks}道内容已评题 / ${s.contentFamilies}题族；旧记录未补内容分`)}</td><td>${cell(pct(s.format),`${s.formatTasks}道已检查题`)}</td><td>${pct(s.constraintRate)}</td><td>${cell(pct(s.automaticDelivery),`${s.automaticTasks}道自动题 / ${s.automaticFamilies}题族，包含失败`)}</td><td>${cell(pct(s.completed),`${s.success}/${s.attempted}次`)}</td><td>${cell(pct(s.qualificationCoverage),`${s.pending}次待复核`)}</td><td>${cell(usd(s.costPerQualified),costNames[s.costState])}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>速度与费用</h2><small>成功请求中位数；每项保留可用样本数</small></div><div class="table-wrap"><table><thead><tr><th>配置</th><th>TTFT / 首正文</th><th>完整耗时P50</th><th>完整耗时P95</th><th>正文TPS · 新</th><th>端到端正文TPS</th><th>字符/秒 · 新</th><th>块间隔P50的中位数</th><th>旧TPS边界估计</th><th>全部尝试费用</th></tr></thead><tbody>${summaries.map(({m,s})=>`<tr><td>${e(m.name)}</td><td>${sec(s.ttft)} / ${sec(s.ttfa)}</td><td>${cell(sec(s.duration),`${s.durationSamples}个成功样本`)}</td><td>${cell(sec(s.durationP95),s.tailState==='mixed_conditions'?'混合题目或配置，不展示尾部估计':s.tailState==='insufficient_sample'?'同条件少于100次，不展示尾部估计':'同条件成功样本≥100；仍非服务承诺')}</td><td>${cell(f(s.bodyTps),`${s.bodyTpsSamples}个可测样本`)}</td><td>${cell(f(s.endToEndTps),`${s.endToEndTpsSamples}个可测样本；包含等待`)}</td><td>${cell(f(s.chars),`${s.charsSamples}个可测样本`)}</td><td>${cell(f(s.chunkGap,2)+' ms','分块不等于token，不叫ITL')}</td><td>${cell(f(s.legacyTps),`${s.legacyTpsSamples}个旧样本，不与新协议合并`)}</td><td>${cell(usd(s.totalCost),`${s.unknownCosts}次费用未知；报价估算，非账单`)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>失败与重复</h2></div><div class="table-wrap"><table><thead><tr><th>配置</th><th>未完整返回</th><th>超时</th><th>限流</th><th>输出截断</th><th>重复题组 / 重复单元</th><th>有合格结论分歧的题组</th></tr></thead><tbody>${summaries.map(({m,s})=>`<tr><td>${e(m.name)}</td><td>${s.errors}</td><td>${s.timeouts}</td><td>${s.limited}</td><td>${s.truncated}</td><td>${s.repeatedGroups} / ${s.repeatUnits}</td><td>${s.disagreeGroups}</td></tr>`).join('')}</tbody></table></div><div class="table-foot">同批次、同题、同repeatIndex的重试归成一个重复单元；不同批次不冒充相同条件。稳定错答不表示能力强。人工待评不补为通过。</div></section>`;
}

export function assessmentView(run){
 const a=run.grading.assessment;if(!a)return '<p class="evidence-meta">历史评分未拆分内容与格式，保留原始规则，不倒填新分数。</p>';
 return `<section class="panel"><div class="panel-head"><h2>内容、格式与合格判定</h2><small>${e(a.protocolId)}</small></div><div class="panel-body"><div class="chips"><span class="tag">内容 ${e(a.contentState)} · ${pct(a.contentScore)}</span><span class="tag">格式 ${e(a.formatState)}</span><span class="tag">${a.qualified===null?'待复核':a.qualified?'合格':'未合格'}</span></div>${[['checks','内容细项'],['constraints','约束细项']].map(([key,title])=>`<h3 style="margin-top:20px">${title}</h3>${a[key].length?`<ul>${a[key].map(c=>`<li>${c.passed?'✓':'×'} ${e(c.label)}${c.points!=null?` · ${f(c.earned)}/${f(c.points)}`:''}</li>`).join('')}</ul>`:'<p class="evidence-meta">此项尚无已完成的评分；人工题须逐项复核。</p>'}`).join('')}${run.grading.rubricReview?`<p class="evidence-meta">公开评审别名：${e(run.grading.rubricReview.reviewer)} · ${e(run.grading.rubricReview.reviewedAt)}</p><ul>${run.grading.rubricReview.items.map(c=>`<li>${e(c.id)}：${e(c.reason)}</li>`).join('')}</ul>`:''}${a.contentState==='pending'?'<button data-review-template="'+e(run.id)+'">下载逐项评分模板 ↓</button>':''}</div></section>`;
}

export function rubricView(task){
 const g=task.grader;if(g.type!=='contract')return '';
 return `<section class="panel"><div class="panel-head"><h2>版本化评分契约</h2><small>${e(g.version)}</small></div><div class="panel-body prose"><p>${e(task.evaluation?.benchmarkRef||'本站任务')} · ${e(task.evaluation?.reviewState||'未标记')} · 题族 ${e(task.evaluation?.familyId||task.id)}</p>${g.criteria?.length?`<div class="table-wrap"><table class="definition-table"><thead><tr><th>细项 / 分值 / 合格下限</th><th>零分</th><th>半分</th><th>满分</th></tr></thead><tbody>${g.criteria.map(c=>`<tr><td>${e(c.label)} · ${f(c.points)}分<small>本项合格下限 ${f(c.passAt)}分</small></td><td>${e(c.zero)}</td><td>${e(c.partial)}</td><td>${e(c.full)}</td></tr>`).join('')}</tbody></table></div>`:''}<details><summary>查看自动检查、容差和约束完整定义</summary><pre class="evidence">${e(JSON.stringify(g,null,2))}</pre></details><p>内容诊断可识别数值等价或单层JSON围栏，但格式约束仍独立检查。多候选数值不会猜答案。人工细项只接受零、半、满分并附证据；关键项未过仍不合格。</p></div></section>`;
}

export function workflowView(){
 return `<div class="notice"><strong>本轮新增API费用：0</strong>　以下命令只做本机模拟与文件校验。无需安装npm/Python包；Python 3.10+、Node 18+。输出使用新目录，保留旧证据。</div><div class="grid2"><section class="panel"><div class="panel-body prose"><h2>1 / 本机完整验收</h2><pre class="evidence">python -m runner.offline_check --out results/new-core-check
python -m runner validate results/new-core-check/public.json
python -m runner.core_audit results/new-core-check/public.json --raw-dir results/new-core-check/raw --out results/new-core-check/audit.json
node --test tests/*.test.mjs
python -m unittest discover -s tests -p 'test_runner*.py'</pre><p>启动临时127.0.0.1 SSE服务，完成24题×3模拟配置、计时、评分、公开白名单导出后自动关闭服务。不读GOAT密钥、不调用外部模型。受限沙盒需允许本机回环连接。</p><p>结果在“数据工作台”导入；固定标记demo。模拟计数器按字符作玩具token计数，只检查公式与链路。</p></div></section><section class="panel"><div class="panel-body prose"><h2>2 / 人工逐项复核</h2><p>在待评运行记录下载模板，填公开别名、每项零/半/满分及具体证据。未填写不会自动变成通过。</p><pre class="evidence">python -m runner.rubric_review results/new-core-check/public.json --run-id RUN_ID --review review.json --out results/reviewed-new.json</pre><p>另存公开结果，不覆盖原始记录；已存在的细项评审不能静默替换。旧版二元review命令不能绕过新评分契约。</p><p>代码题暂不发布pass@1；可用 python -m runner.svg_check answer.svg 检查受限SVG格式，但这不等于渲染或视觉评分。开放题评分仍需人工工作。</p></div></section></div><section class="panel"><div class="panel-body prose"><h2>3 / 将来的真实采集</h2><p>重新确认GOAT可用型号、价格与预算，建立新配置和批次后才执行。使用datasets/core_v1.json，配置metricProtocol为core-client-v1、suiteId为zhufeng-core-pilot-v1。先运行plan，真实run仍要求显式execute和allow-paid。网页不接收密钥。</p><p>本轮不授权新增调用。当前六个目标配置只是历史目录，价格为空；没有真实新成绩。题目难度及区分度待预算内试测校准，不能把离线检查当成模型排名。</p><a href="#system">查看全部指标与未接入项 ↗</a></div></section>`;
}
